.sgp{--forest:#193728;--moss:#3f684a;--sage:#91a78b;--ivory:#f5f0e6;--cream:#eadcc4;--blush:#cf9ca6;--gold:#c9a56b;--shadow:0 18px 52px rgba(8,23,17,.28);position:relative;background:linear-gradient(180deg,#eaf1e5,#cad7c2);color:var(--forest);font-family:var(--font-body, Poppins),sans-serif;overflow:hidden}.sgp *{box-sizing:border-box}.sgp img{display:block;max-width:100%}.sgp__scenes{height:100svh;overflow-y:auto;scroll-snap-type:y mandatory;scroll-behavior:smooth}.sgp__scene{position:relative;min-height:100svh;scroll-snap-align:start;overflow:hidden;display:flex;align-items:center;justify-content:center;padding:84px 18px 30px;isolation:isolate}.sgp__scene:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(245,240,230,.18),rgba(17,38,28,.10) 60%,rgba(245,240,230,.06));z-index:-1}.sgp__sceneBg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-4;filter:saturate(1.02) contrast(1.02)}.sgp__layerSet{position:absolute;inset:0;pointer-events:none;z-index:-2}.sgp__layer{position:absolute;will-change:transform;filter:drop-shadow(0 10px 20px rgba(0,0,0,.12))}.sgp__layer--back{inset:auto -8% 18% -8%;width:116%;opacity:.45;mix-blend-mode:multiply}.sgp__layer--tree.left{left:-12%;bottom:-2%;width:42%}.sgp__layer--tree.right{right:-12%;bottom:-2%;width:42%}.sgp__layer--branch.left{left:-2%;top:-2%;width:32%;transform-origin:left top}.sgp__layer--branch.right{right:-2%;top:-2%;width:32%;transform-origin:right top}.sgp__layer--flower.lf{left:-4%;bottom:0;width:26%}.sgp__layer--flower.rf{right:-4%;bottom:0;width:26%}.sgp__layer--flower.lm{left:-2%;bottom:0;width:22%}.sgp__layer--flower.rm{right:-2%;bottom:0;width:22%}.sgp__layer--bottom.left{left:-2%;bottom:-1%;width:28%}.sgp__layer--bottom.center{left:50%;transform:translateX(-50%);bottom:-1%;width:36%}.sgp__layer--bottom.right{right:-2%;bottom:-1%;width:28%}.sgp__layer--gazebo{right:7%;bottom:18%;width:26%;opacity:.92}.sgp__layer--bridge{left:50%;bottom:13%;transform:translateX(-50%);width:46%}.sgp__layer--path{left:50%;bottom:-1%;transform:translateX(-50%);width:58%}.sgp__layer--pond{left:50%;bottom:-1%;transform:translateX(-50%);width:90%;opacity:.75}.sgp__layer--step{left:50%;bottom:7%;transform:translateX(-50%);width:28%}.sgp__layer--sign{left:9%;bottom:14%;width:24%}.sgp__layer--lamp.left{left:10%;bottom:14%;width:12%}.sgp__layer--lamp.right{right:10%;bottom:14%;width:12%}.sgp__layer--grass.left{left:0;bottom:-2%;width:25%}.sgp__layer--grass.right{right:0;bottom:-2%;width:25%;transform:scaleX(-1)}.sgp__layer--arch{left:50%;bottom:10%;transform:translateX(-50%);width:min(62vw,360px)}.sgp__toolbar{position:fixed;top:14px;right:14px;z-index:30;display:flex;gap:10px;align-items:center}.sgp__music{width:42px;height:42px;border:none;border-radius:999px;background:rgba(25,55,40,.84);color:#fff;font:700 1rem/1 var(--font-body, Poppins);box-shadow:var(--shadow);cursor:pointer;backdrop-filter:blur(8px)}.sgp__dots{display:flex;gap:6px;padding:10px 12px;border-radius:999px;background:rgba(245,240,230,.72);backdrop-filter:blur(8px);box-shadow:var(--shadow)}.sgp__dot{width:8px;height:8px;border-radius:50%;background:rgba(25,55,40,.28);transition:all .25s ease}.sgp__dot.is-active{background:var(--gold);transform:scale(1.22)}.sgp__scrollHint{position:fixed;left:50%;top:16px;transform:translateX(-50%);z-index:28;background:rgba(245,240,230,.78);padding:10px 16px;border-radius:999px;color:var(--forest);font:600 .72rem var(--font-body, Poppins);letter-spacing:.08em;backdrop-filter:blur(8px);box-shadow:var(--shadow)}.glass{width:min(92vw,820px);background:linear-gradient(180deg,rgba(245,240,230,.80),rgba(255,255,255,.64));border:1px solid rgba(255,255,255,.65);box-shadow:0 24px 80px rgba(22,45,32,.18),inset 0 1px 0 rgba(255,255,255,.45);backdrop-filter:blur(16px);border-radius:30px;padding:28px 22px;position:relative}.glass:before{content:'';position:absolute;inset:8px;border-radius:24px;border:1px solid rgba(201,165,107,.28);pointer-events:none}.glass--wide{width:min(94vw,980px)}.glass--narrow{width:min(92vw,560px)}.sgp__content{position:relative;z-index:2}.sgp__content--cover{text-align:center;padding-top:42px;padding-bottom:42px}.sgp__content--center{text-align:center}.sgp__eyebrow,.sgp__sectionMini{font:800 .72rem/1 var(--font-body, Poppins);letter-spacing:.23em;color:var(--moss);text-transform:uppercase}.sgp__headline{margin:10px 0 4px;font:700 clamp(3rem,11vw,5.6rem)/.9 var(--font-title, 'Cormorant Garamond'),serif;color:var(--forest)}.sgp__dateHero{margin:12px 0 0;font:600 1.02rem/1.4 var(--font-body, Poppins);color:var(--moss)}.sgp__tagline{margin:14px auto 0;max-width:540px;font:600 clamp(.94rem,3vw,1.06rem)/1.6 var(--font-body, Poppins);color:#4d6655}.sgp__lead,.sgp__copy{margin:16px auto 0;max-width:680px;font:500 clamp(.92rem,3.5vw,1rem)/1.85 var(--font-body, Poppins);color:#32513e}.sgp__sectionTitle{margin:8px 0 0;font:700 clamp(2rem,7vw,3.5rem)/1 var(--font-title, 'Cormorant Garamond'),serif;color:var(--forest)}.sgp__coupleGrid{display:grid;grid-template-columns:1fr 1.25fr 1fr;gap:18px;align-items:center;margin-top:26px}.sgp__portrait{text-align:center}.sgp__photoWrap{position:relative;width:min(100%,240px);aspect-ratio:4/5;margin:0 auto;display:grid;place-items:center}.sgp__photo{position:absolute;inset:11% 12% 11% 12%;width:76%;height:78%;object-fit:cover;border-radius:28px;box-shadow:0 12px 30px rgba(0,0,0,.16)}.sgp__frame{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;pointer-events:none}.sgp__portrait figcaption{margin-top:10px}.sgp__role{display:block;font:700 .74rem/1.2 var(--font-body, Poppins);letter-spacing:.2em;color:var(--moss);text-transform:uppercase;margin-bottom:5px}.sgp__portrait strong{font:700 1.4rem/1.1 var(--font-title, 'Cormorant Garamond'),serif;color:var(--forest)}.sgp__coupleMain img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:28px;border:1px solid rgba(255,255,255,.7);box-shadow:0 18px 44px rgba(0,0,0,.12)}.sgp__marker{width:44px;height:44px;margin:18px auto 0;animation:bob 2.6s ease-in-out infinite}.sgp__dateCard{margin-top:18px;padding:18px;border-radius:22px;background:rgba(255,255,255,.38);border:1px solid rgba(201,165,107,.35)}.sgp__dateDisplay{font:700 clamp(1.8rem,8vw,3rem)/1 var(--font-title, 'Cormorant Garamond'),serif;color:var(--forest)}.sgp__timeDisplay{margin-top:8px;font:700 1rem/1.5 var(--font-body, Poppins);color:#4d6655}.sgp__countdown{margin-top:14px;padding:14px 16px;border-radius:16px;background:rgba(25,55,40,.08);border:1px dashed rgba(25,55,40,.22);font:700 .92rem/1.5 var(--font-body, Poppins);color:var(--forest)}.sgp__mapWrap{margin-top:18px;border-radius:20px;overflow:hidden;border:1px solid rgba(255,255,255,.8);box-shadow:0 16px 36px rgba(0,0,0,.12)}.sgp__mapWrap iframe{display:block;width:100%;height:280px;border:0}.sgp__content--rsvp{display:grid;gap:16px}.sgp__form{display:grid;gap:8px}.sgp__form label{font:800 .74rem/1.2 var(--font-body, Poppins);letter-spacing:.12em;text-transform:uppercase;color:var(--moss)}.sgp__form select,.sgp__form input,.sgp__form textarea{width:100%;border:none;border-radius:16px;padding:14px 16px;background:rgba(255,255,255,.74);color:var(--forest);font:500 .95rem/1.5 var(--font-body, Poppins);box-shadow:inset 0 0 0 1px rgba(25,55,40,.12)}.sgp__btn{margin-top:4px;border:none;border-radius:16px;padding:14px 18px;background:linear-gradient(180deg,#d7bb8a,#c9a56b);color:#213d2e;font:800 .82rem/1 var(--font-body, Poppins);letter-spacing:.16em;cursor:pointer;box-shadow:0 8px 18px rgba(107,80,38,.25)}.sgp__note{margin:2px 0 0;font:600 .8rem/1.45 var(--font-body, Poppins);color:#496656}.sgp__note.ok{color:#2d7b4f}.sgp__note.err{color:#a34d62}.sgp__messages{list-style:none;padding:0;margin:6px 0 0;display:grid;gap:10px;max-height:240px;overflow:auto}.sgp__messageItem{padding:14px 16px;border-radius:16px;background:rgba(255,255,255,.46);border:1px solid rgba(255,255,255,.7)}.sgp__messageItem strong{display:block;font:700 1rem/1.1 var(--font-title, 'Cormorant Garamond'),serif;color:var(--forest)}.sgp__messageItem p{margin:6px 0 4px;font:500 .9rem/1.6 var(--font-body, Poppins);color:#32513e}.sgp__messageItem time{font:600 .72rem/1.3 var(--font-body, Poppins);color:#647e6c}.sgp__empty{padding:16px;border-radius:16px;border:1px dashed rgba(25,55,40,.22);text-align:center;color:#496656;font:600 .86rem/1.5 var(--font-body, Poppins)}.sgp__petals{position:fixed;inset:0;pointer-events:none;z-index:20;overflow:hidden}.sgp__petal{position:absolute;top:-12vh;width:30px;opacity:.86;will-change:transform,opacity;animation-name:petalFall;animation-timing-function:linear;animation-iteration-count:infinite}.sgp__butterflies{pointer-events:none;position:fixed;inset:0;z-index:21}.sgp__butterfly{position:absolute;width:48px;opacity:.9;animation:butterFloat 12s ease-in-out infinite}.sgp__butterfly.b1{left:9%;top:18%;animation-delay:0s}.sgp__butterfly.b2{right:12%;top:30%;animation-delay:2s}.sgp__butterfly.b3{left:20%;bottom:18%;animation-delay:4.5s}.sgp__butterfly.b4{right:22%;bottom:26%;animation-delay:6s}.sway-slower{animation:sway 8.4s ease-in-out infinite}.sway-slow{animation:sway 6.5s ease-in-out infinite}.sway-mid{animation:sway 5.1s ease-in-out infinite}.sway-wide{animation:swayWide 7.3s ease-in-out infinite}.sgp__scene.is-active .glass{animation:fadeUp .8s ease both}.sgp__scene.is-active .sgp__sectionTitle,.sgp__scene.is-active .sgp__headline{animation:fadeUp .95s ease both}.sgp__scene.is-active .sgp__copy,.sgp__scene.is-active .sgp__lead,.sgp__scene.is-active .sgp__dateCard{animation:fadeUp 1.15s ease both}.@keyframes sway{0%,100%{transform:translate3d(0,0,0) rotate(-2deg)}50%{transform:translate3d(0,-6px,0) rotate(2deg)}}@keyframes swayWide{0%,100%{transform:translate3d(0,0,0) rotate(-3deg)}50%{transform:translate3d(0,-8px,0) rotate(3deg)}}@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}@keyframes fadeUp{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:translateY(0)}}@keyframes petalFall{0%{transform:translate3d(0,-10vh,0) rotate(0deg)}100%{transform:translate3d(var(--drift),110vh,0) rotate(540deg)}}@keyframes butterFloat{0%,100%{transform:translate3d(0,0,0) rotate(-5deg)}25%{transform:translate3d(12px,-16px,0) rotate(5deg)}50%{transform:translate3d(28px,4px,0) rotate(-3deg)}75%{transform:translate3d(6px,18px,0) rotate(4deg)}}@media (max-width: 900px){.sgp__coupleGrid{grid-template-columns:1fr;gap:14px}.sgp__coupleMain{order:-1}.sgp__layer--tree.left,.sgp__layer--tree.right{width:56%;opacity:.72}.sgp__layer--arch{width:min(78vw,360px)}.sgp__mapWrap iframe{height:240px}.sgp__scrollHint{top:auto;bottom:12px;font-size:.68rem}.sgp__toolbar{top:10px;right:10px}.glass{padding:24px 18px 22px;border-radius:24px}.glass:before{inset:7px;border-radius:18px}.sgp__headline{font-size:clamp(2.5rem,14vw,4rem)}}
.sgp img[src=""], .sgp img:not([src]){display:none}
.sgp__preload{display:none!important}
.sgp__layer{--baseX:0px;--baseY:0px;--parallaxY:0px;--swayY:0px;--swayRot:0deg;--flipX:1;transform:translate(var(--baseX),calc(var(--baseY) + var(--parallaxY) + var(--swayY))) scaleX(var(--flipX)) rotate(var(--swayRot));}
.sgp__layer--bottom.center,.sgp__layer--bridge,.sgp__layer--path,.sgp__layer--pond,.sgp__layer--step,.sgp__layer--arch,.sgp__layer--frame{--baseX:-50%}
