(function(){
  var root=document.querySelector('.sgp');
  if(!root||root.dataset.inited)return;root.dataset.inited='1';
  var scroller=root.querySelector('.js-scenes');
  var scenes=[].slice.call(root.querySelectorAll('.js-scene'));
  var dots=[].slice.call(root.querySelectorAll('.sgp__dot'));
  var hint=root.querySelector('.sgp__scrollHint');
  var countdown=root.querySelector('.js-countdown');
  var petalsBox=root.querySelector('.js-petals');
  var musicBtn=root.querySelector('.js-music');
  var bgmAudio=root.querySelector('.js-bgm');
  var bgmSrc=root.querySelector('.js-bgm-src');
  var preload=root.querySelector('.js-preload');
  function q(sel){return root.querySelector(sel);}  
  function qpre(id){return preload?preload.querySelector('[data-imgid="'+id+'"]'):null;}
  function tzOffset(tz){return tz==='WIT'?9:tz==='WITA'?8:7;}
  function getDate(){var d=q('[data-field="event_date"]'),t=q('[data-field="event_time"]'),z=q('[data-field="event_timezone"]');var ds=d?d.textContent.trim():'',ts=t?t.textContent.trim():'00:00',tz=z?z.textContent.trim():'WIB';if(!ds)return null;var parts=ds.split('-'),tp=ts.split(':');if(parts.length!==3)return null;var utc=Date.UTC(+parts[0],+parts[1]-1,+parts[2],+(tp[0]||0)-tzOffset(tz),+(tp[1]||0),0);var date=new Date(utc);return isNaN(date.getTime())?null:date;}
  function tick(){if(!countdown)return;var date=getDate();if(!date){countdown.textContent='';return;}var diff=date.getTime()-Date.now();if(diff<=0){countdown.textContent='Hari bahagia telah tiba!';return;}var s=Math.floor(diff/1000),dd=Math.floor(s/86400),hh=Math.floor((s%86400)/3600),mm=Math.floor((s%3600)/60),ss=s%60;countdown.textContent=dd+' hari · '+hh+' jam · '+mm+' menit · '+ss+' detik';}
  tick(); setInterval(tick,1000);

  var petalSources=['petal_1','petal_2','petal_3','petal_4'].map(function(k){var el=qpre(k);return el?(el.currentSrc||el.src):'';}).filter(Boolean);
  var leafSources=['leaf_fall_1','leaf_fall_2'].map(function(k){var el=qpre(k);return el?(el.currentSrc||el.src):'';}).filter(Boolean);
  if(petalsBox && petalSources.length){
    var all=petalSources.concat(leafSources.slice(0,1));
    for(var i=0;i<30;i++){
      var p=document.createElement('img');
      p.className='sgp__petal';
      p.src=all[i%all.length];
      p.alt='';
      p.style.left=(Math.random()*100)+'vw';
      p.style.animationDuration=(10+Math.random()*10)+'s';
      p.style.animationDelay=(-Math.random()*18)+'s';
      p.style.setProperty('--drift', ((Math.random()*180)-90)+'px');
      p.style.width=(16+Math.random()*20)+'px';
      p.style.opacity=(0.52+Math.random()*0.35).toFixed(2);
      petalsBox.appendChild(p);
    }
  }

  var observer=new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      var idx=scenes.indexOf(entry.target);
      if(entry.isIntersecting && entry.intersectionRatio>0.52){
        scenes.forEach(function(s){s.classList.remove('is-active');});
        entry.target.classList.add('is-active');
        dots.forEach(function(d){d.classList.remove('is-active');});
        if(dots[idx])dots[idx].classList.add('is-active');
        if(hint)hint.style.opacity=idx===0?'1':'0';
      }
    });
  },{root:scroller,threshold:[0.55]});
  scenes.forEach(function(s){observer.observe(s);});
  if(scenes[0])scenes[0].classList.add('is-active');

  function swayProfile(el){
    var speed=0.8, ampY=0, ampRot=0;
    if(el.classList.contains('sway-slower')){speed=0.7;ampY=4;ampRot=1.8;}
    else if(el.classList.contains('sway-slow')){speed=0.95;ampY=5;ampRot=2.2;}
    else if(el.classList.contains('sway-wide')){speed=0.78;ampY=8;ampRot=4.0;}
    else if(el.classList.contains('sway-mid')){speed=1.15;ampY=7;ampRot=3.2;}
    return {speed:speed,ampY:ampY,ampRot:ampRot};
  }

  function paint(time){
    var t=(time||0)*0.001;
    var vh=scroller.clientHeight||window.innerHeight;
    scenes.forEach(function(scene, sceneIdx){
      var rect=scene.getBoundingClientRect();
      var center=(rect.top + rect.height/2) - vh/2;
      var layers=scene.querySelectorAll('[data-depth]');
      layers.forEach(function(el, i){
        var depth=parseFloat(el.getAttribute('data-depth')||'0');
        var extra=-center*depth*0.18;
        var profile=swayProfile(el);
        var phase=(sceneIdx*0.9)+(i*0.73);
        var swayY=Math.sin(t*profile.speed + phase)*profile.ampY;
        var swayRot=Math.sin(t*profile.speed*1.1 + phase*1.23)*profile.ampRot;
        el.style.setProperty('--parallaxY', extra.toFixed(2)+'px');
        el.style.setProperty('--swayY', swayY.toFixed(2)+'px');
        el.style.setProperty('--swayRot', swayRot.toFixed(2)+'deg');
      });
      var butterflies=scene.querySelectorAll('.sgp__coverButterfly');
      butterflies.forEach(function(el, i){
        var bobY=Math.sin(t*1.2 + i*1.7)*7;
        var bobX=Math.cos(t*0.9 + i*1.3)*5;
        var rot=Math.sin(t*1.05 + i)*6;
        el.style.transform='translate3d('+bobX.toFixed(2)+'px,'+bobY.toFixed(2)+'px,0) rotate('+rot.toFixed(2)+'deg)';
      });
    });
    requestAnimationFrame(paint);
  }
  requestAnimationFrame(paint);

  function syncAudio(){if(!bgmAudio)return;var url=bgmSrc?bgmSrc.textContent.trim():'';if(url&&bgmAudio.getAttribute('src')!==url)bgmAudio.setAttribute('src',url);}
  function playAudio(){if(!bgmAudio)return;syncAudio();try{var p=bgmAudio.play();if(p&&p.catch)p.catch(function(){});}catch(e){}}
  var wanted=true;
  function updateMusicBtn(){if(musicBtn){musicBtn.textContent=wanted?'♪':'×';musicBtn.setAttribute('aria-pressed', wanted?'true':'false');}}
  updateMusicBtn();
  function prime(){if(wanted)playAudio();window.removeEventListener('pointerdown',prime);window.removeEventListener('keydown',prime);}
  window.addEventListener('pointerdown', prime, {passive:true, once:true});
  window.addEventListener('keydown', prime, {once:true});
  if(musicBtn)musicBtn.addEventListener('click', function(e){e.preventDefault();wanted=!wanted;if(wanted)playAudio(); else if(bgmAudio)bgmAudio.pause();updateMusicBtn();});
  if(bgmSrc && 'MutationObserver' in window){ new MutationObserver(function(){syncAudio(); if(wanted&&bgmAudio&&bgmAudio.paused)playAudio();}).observe(bgmSrc,{childList:true,characterData:true,subtree:true}); }
})();
